def solve(text, required):
    if not required:
        return 0

    required_set = set(required)
    text_len = len(text)

    # If text doesn't contain all required characters, impossible
    text_chars = set(text)
    if len(text_chars.intersection(required_set)) != len(required_set):
        return -1

    min_len = float('inf')

    # Try all possible substrings
    for i in range(text_len):
        seen = {}
        for j in range(i, text_len):
            char = text[j]
            seen[char] = seen.get(char, 0) + 1

            # Check if current substring contains all required characters
            if all(char in seen and seen[char] > 0 for char in required_set):
                # Check if all required characters are present (at least once)
                if all(char in seen for char in required_set):
                    # Calculate length of current substring
                    current_len = j - i + 1
                    min_len = min(min_len, current_len)

    return min_len if min_len != float('inf') else -1
