def solve(items):
    if not items:
        return 0

    max_length = 0
    n = len(items)

    for i in range(n):
        seen = set()
        for j in range(i, n):
            if items[j] in seen:
                break
            seen.add(items[j])
            max_length = max(max_length, j - i + 1)

    return max_length
